// n8n Code Node: Check Duplicate
// Mode: Run Once for Each Item
// Checks workflow static data for already-processed Gmail message IDs.
// Returns [] (empty) to stop execution for duplicates.
// Returns item with _message_id added for new messages.

const state = $getWorkflowStaticData('global');
state.processed = state.processed || {};

const msgId = $json.id || $json.messageId || '';

if (!msgId) {
  // No message ID available — let through (cannot deduplicate without an ID)
  return { json: { ...$json, _message_id: '' } };
}

if (state.processed[msgId]) {
  // Already processed — return empty array to stop this execution branch silently
  return [];
}

return { json: { ...$json, _message_id: msgId } };

// n8n Code Node: Classify Email
// Mode: Run Once for Each Item
// Input: Gmail Trigger output
// Output: original item + _classification { is_meeting, score, reason, kind }

const MEETING_SENDERS = new Set([
  'noreply-calendar-invitation@google.com',
  'calendar-notification@google.com',
  'gemini-notes@google.com',
  'no-reply@zoom.us',
  'no-reply@us05web.zoom.us',
  'noreply@zoom.us',
  'no-reply@meet.google.com',
  'no-reply@chime.aws',
  'noreply@webex.com',
  'noreply@teams.microsoft.com',
  'fathom@fathom.video',
  'noreply@fathom.video',
  'team@otter.ai',
  'noreply@otter.ai',
  'noreply@fireflies.ai',
  'no-reply@fireflies.ai',
  'noreply@read.ai',
  'no-reply@calendly.com',
  'scheduling@x.ai',
]);

const MEETING_DOMAINS = new Set([
  'fathom.video',
  'otter.ai',
  'fireflies.ai',
  'read.ai',
  'calendly.com',
  'savvycal.com',
  'zoom.us',
  'webex.com',
  'teams.microsoft.com',
  'meet.google.com',
  'chime.aws',
]);

const SUBJECT_HINTS = [
  /\binvitation\b/i,
  /\bmeeting\b/i,
  /\bcall\b/i,
  /\bsync\b/i,
  /\b1:1\b/i,
  /\bone[- ]on[- ]one\b/i,
  /\bstandup\b/i,
  /\bstand-up\b/i,
  /\bcatch[- ]up\b/i,
  /\bcheck[- ]in\b/i,
  /\bdiscussion\b/i,
  /\bagenda\b/i,
  /\binterview\b/i,
  /\bdebrief\b/i,
  /\bplanning\b/i,
  /\bretro(spective)?\b/i,
  /\breview\b/i,
  /\bworkshop\b/i,
  /\bdemo\b/i,
  /\bkick[- ]?off\b/i,
  /\bintro\b/i,
  /\bchat\b/i,
  /\bquick (call|chat|sync)\b/i,
  /\baction items?\b/i,
  /\bnotes?(\s+from|:)\b/i,
  /\brecap of\b/i,
  /\b(transcript|recording) (of|from|for)\b/i,
  /\b(zoom|teams|meet|webex|chime) (recording|meeting|invite)\b/i,
];

const BODY_HINTS = /meeting (link|recording|transcript)|join (the )?meeting|google meet|zoom\.us\/(j|my)\/|teams\.microsoft\.com\/l\/meetup|action items?|attendees?:|agenda|recap|begin:vcalendar/i;

// Extract sender email from "Display Name <email@domain.com>" format
const rawFrom = ($json.from || $json.From || '').toLowerCase();
const emailMatch = rawFrom.match(/<([^>]+)>/);
const senderEmail = emailMatch ? emailMatch[1] : rawFrom.trim();
const senderDomain = senderEmail.includes('@') ? senderEmail.split('@')[1] : '';

const subject = ($json.subject || $json.Subject || '').toLowerCase();
const body = ($json.text || $json.body || $json.snippet || '').toLowerCase();

let score = 0;
const reasons = [];
let kind = 'other';

if (MEETING_SENDERS.has(senderEmail)) {
  score += 0.8;
  reasons.push(`sender:${senderEmail}`);
}
if (MEETING_DOMAINS.has(senderDomain)) {
  score += 0.5;
  reasons.push(`domain:${senderDomain}`);
}
if (SUBJECT_HINTS.some(re => re.test(subject))) {
  score += 0.4;
  reasons.push('subject-hint');
}
if (BODY_HINTS.test(body)) {
  score += 0.3;
  reasons.push('body-hint');
}
if (body.includes('begin:vcalendar')) {
  score += 0.5;
  reasons.push('vcalendar');
}

// Kind detection
if (body.includes('begin:vcalendar') || subject.includes('invitation')) {
  kind = 'invite';
} else if (subject.includes('canceled event')) {
  kind = 'invite';
} else if (subject.includes('recording') || body.slice(0, 500).includes('recording')) {
  kind = 'recording';
} else if (subject.includes('transcript') || body.slice(0, 1000).includes('transcript')) {
  kind = 'transcript';
} else if (senderEmail === 'gemini-notes@google.com' || body.slice(0, 200).includes('notes from')) {
  kind = 'transcript';
} else if (subject.includes('recap') || subject.includes('notes from') || body.includes('action items')) {
  kind = 'recap';
} else if (MEETING_DOMAINS.has(senderDomain)) {
  kind = 'recap';
} else if (score >= 0.4) {
  kind = 'conversation';
}

return {
  json: {
    ...$json,
    _classification: {
      is_meeting: score >= 0.6,
      score: Math.round(score * 100) / 100,
      reason: reasons.join(', ') || 'no signals',
      kind,
    },
  },
};

// n8n Code Node: Build Groq API Request Body
// Mode: Run Once for Each Item
// Input: Classify Email output
// Output: { _groq_body: {...}, ...original fields }

const SYSTEM_PROMPT = `You analyze meeting-related emails (calendar invites, recap threads, recording links, auto-transcripts from Otter/Fathom/Fireflies/Read.ai, intros, scheduling messages) and return a strict JSON object describing the meeting.

Schema (return ONLY valid JSON, no prose, no markdown fences):
{
  "title": "string — short human-readable title, e.g. Q3 pricing review w/ Alice",
  "kind": "invite|recording|transcript|recap|conversation|other",
  "platform": "google-meet|zoom|teams|webex|chime|in-person|phone|unknown",
  "date": "YYYY-MM-DD or null",
  "start_time": "HH:MM (24h) or null",
  "end_time": "HH:MM (24h) or null",
  "duration_minutes": "integer or null",
  "location": "string or null",
  "attendees": [
    { "name": "string or null", "email": "string or null", "role": "host|organizer|attendee|optional|null" }
  ],
  "summary": "2-4 sentence plain prose summary",
  "topics": ["short kebab-case tags, 3-8 items"],
  "decisions": ["each a single declarative sentence"],
  "action_items": [
    { "owner": "string or null", "task": "string", "due": "YYYY-MM-DD or null", "done": false, "priority": "high|medium|low" }
  ],
  "key_quotes": ["up to 3 short quotes under 25 words, only if transcript included"],
  "links": ["recording/transcript/doc URLs, deduped"],
  "sentiment": "positive|neutral|mixed|tense|null",
  "follow_up_needed": true,
  "confidence": 0.0
}

Rules:
- If the email is a scheduling back-and-forth with no confirmed time, set kind = "conversation".
- If the email is clearly NOT meeting-related, set confidence < 0.3 and leave most fields empty/null.
- Names: Title Case. Emails: lowercase.
- Topics: 1-3 words, kebab-case, no leading #.
- Action item priority: "high" = blocking, urgent, ASAP, must be done this week or before next meeting; "medium" = important with deadline within the month; "low" = nice-to-have, far future, or no clear deadline.
- Output valid JSON only. No markdown. No commentary.`;

const subject  = $json.subject  || $json.Subject  || '(no subject)';
const from     = $json.from     || $json.From     || '';
const to       = $json.to       || $json.To       || '';
const date     = $json.date     || $json.Date     || '';
const body     = $json.text     || $json.body     || $json.snippet || '';

// Truncate body to 18000 chars to stay within token limits
const truncated = body.length > 18000
  ? body.slice(0, 9000) + '\n\n…[truncated]…\n\n' + body.slice(-9000)
  : body;

const userPrompt = `SUBJECT: ${subject}
FROM:    ${from}
TO:      ${to}
DATE:    ${date}

--- BODY ---
${truncated}`;

return {
  json: {
    ...$json,
    _groq_body: {
      model: 'llama-3.3-70b-versatile',
      temperature: 0.2,
      response_format: { type: 'json_object' },
      messages: [
        { role: 'system', content: SYSTEM_PROMPT },
        { role: 'user',   content: userPrompt },
      ],
    },
  },
};

// n8n Code Node: Parse LLM Response
// Mode: Run Once for Each Item
// Input: Groq HTTP Request output
// Output: original email fields + _extracted { title, attendees, action_items, ... }

const raw = $json.choices?.[0]?.message?.content || '';

// Strip markdown fences if model ignores response_format instruction
let text = raw.trim();
if (text.startsWith('```')) {
  text = text.replace(/^```[a-zA-Z]*\n?/, '').replace(/\n?```\s*$/, '');
  text = text.trim();
}

let parsed;
try {
  parsed = JSON.parse(text);
} catch (_) {
  // Best-effort: find the first balanced { } block
  const start = text.indexOf('{');
  if (start === -1) throw new Error('No JSON object in LLM response: ' + text.slice(0, 200));

  let depth = 0, inStr = false, esc = false;
  for (let i = start; i < text.length; i++) {
    const ch = text[i];
    if (inStr) {
      if (esc) { esc = false; continue; }
      if (ch === '\\') { esc = true; continue; }
      if (ch === '"') inStr = false;
      continue;
    }
    if (ch === '"') inStr = true;
    else if (ch === '{') depth++;
    else if (ch === '}') {
      depth--;
      if (depth === 0) {
        parsed = JSON.parse(text.slice(start, i + 1));
        break;
      }
    }
  }
  if (!parsed) throw new Error('Could not extract JSON from LLM response');
}

// Pull the email fields from the upstream Build Groq Request node
const email = $('Build Groq Request').item.json;

return {
  json: {
    // Preserve original email metadata
    _email_subject:    email.subject  || email.Subject  || '',
    _email_from:       email.from     || email.From     || '',
    _email_date:       email.date     || email.Date     || '',
    _email_message_id: email.id       || email.messageId || '',
    // Forward _message_id set by Check Duplicate (survives through Groq LLM via Build Groq Request)
    _message_id:       email._message_id || email.id || email.messageId || '',
    _classification:   email._classification,

    // Structured extraction result
    _extracted: {
      title:            parsed.title            || 'Meeting',
      kind:             parsed.kind             || 'other',
      platform:         parsed.platform         || 'unknown',
      date:             parsed.date             || null,
      start_time:       parsed.start_time       || null,
      end_time:         parsed.end_time         || null,
      duration_minutes: parsed.duration_minutes || null,
      location:         parsed.location         || null,
      attendees:        parsed.attendees        || [],
      summary:          parsed.summary          || '',
      topics:           (parsed.topics || []).map(t => t.toLowerCase().trim()),
      decisions:        parsed.decisions        || [],
      action_items:     parsed.action_items     || [],
      key_quotes:       parsed.key_quotes       || [],
      links:            parsed.links            || [],
      sentiment:        parsed.sentiment        || null,
      follow_up_needed: !!parsed.follow_up_needed,
      confidence:       parseFloat(parsed.confidence) || 0,
    },
  },
};

// n8n Code Node: Mark as Processed
// Mode: Run Once for Each Item
// Writes Gmail message ID + metadata to workflow static data.
// Runs after the confidence gate — only emails that pass both gates are recorded.
// This is the deduplication commit point.

const state = $getWorkflowStaticData('global');
state.processed = state.processed || {};

const msgId = $json._message_id || $json._email_message_id || '';
if (msgId) {
  state.processed[msgId] = {
    processed_at: new Date().toISOString(),
    kind: $json._extracted?.kind || 'unknown',
    confidence: $json._extracted?.confidence || 0,
  };
}

return { json: $json };

// n8n Code Node: Build Confluence Page
// Mode: Run Once for Each Item
// Builds _confluence_title (string) and _confluence_body (HTML string) from _extracted.
// Replaces the 400-char inline template previously embedded in the Confluence node.

const e = $json._extracted;

function escapeHtml(str) {
  if (!str && str !== 0) return '';
  return String(str)
    .replace(/&/g, '&amp;')
    .replace(/</g, '&lt;')
    .replace(/>/g, '&gt;')
    .replace(/"/g, '&quot;');
}

function badge(priority) {
  const p = (priority || 'low').toLowerCase();
  if (p === 'high')   return '<strong style="color:#bf2600">[HIGH]</strong>';
  if (p === 'medium') return '<strong style="color:#ff8b00">[MED]</strong>';
  return '<strong style="color:#505f79">[LOW]</strong>';
}

// Title: "YYYY-MM-DD — Meeting Title" or just "Meeting Title"
const _confluence_title = (e.date ? escapeHtml(e.date) + ' — ' : '') + escapeHtml(e.title || 'Meeting');

const parts = [];

// Summary
parts.push('<h2>Summary</h2>');
parts.push('<p>' + escapeHtml(e.summary || 'No summary available.') + '</p>');

// Meeting Details table — only rows where data exists
parts.push('<h2>Meeting Details</h2><table><tbody>');
if (e.date)             parts.push('<tr><td><strong>Date</strong></td><td>' + escapeHtml(e.date) + '</td></tr>');
if (e.platform)         parts.push('<tr><td><strong>Platform</strong></td><td>' + escapeHtml(e.platform) + '</td></tr>');
if (e.duration_minutes) parts.push('<tr><td><strong>Duration</strong></td><td>' + escapeHtml(String(e.duration_minutes)) + ' min</td></tr>');
if (e.start_time)       parts.push('<tr><td><strong>Time</strong></td><td>' + escapeHtml(e.start_time) + (e.end_time ? ' &ndash; ' + escapeHtml(e.end_time) : '') + '</td></tr>');
if (e.location)         parts.push('<tr><td><strong>Location</strong></td><td>' + escapeHtml(e.location) + '</td></tr>');
if (e.sentiment)        parts.push('<tr><td><strong>Sentiment</strong></td><td>' + escapeHtml(e.sentiment) + '</td></tr>');
parts.push('<tr><td><strong>Follow-up needed</strong></td><td>' + (e.follow_up_needed ? 'Yes' : 'No') + '</td></tr>');
parts.push('</tbody></table>');

// Attendees
if (e.attendees && e.attendees.length > 0) {
  parts.push('<h2>Attendees</h2><ul>');
  for (const a of e.attendees) {
    const name  = escapeHtml(a.name  || a.email || 'Unknown');
    const email = a.email ? ' (' + escapeHtml(a.email) + ')' : '';
    const role  = a.role  ? ' — ' + escapeHtml(a.role) : '';
    parts.push('<li>' + name + email + role + '</li>');
  }
  parts.push('</ul>');
}

// Decisions
if (e.decisions && e.decisions.length > 0) {
  parts.push('<h2>Decisions</h2><ul>');
  for (const d of e.decisions) parts.push('<li>' + escapeHtml(d) + '</li>');
  parts.push('</ul>');
}

// Action Items
if (e.action_items && e.action_items.length > 0) {
  parts.push('<h2>Action Items</h2><ul>');
  for (const a of e.action_items) {
    const owner = a.owner ? '<strong>' + escapeHtml(a.owner) + '</strong> — ' : '';
    const due   = a.due   ? ' <em>(due ' + escapeHtml(a.due) + ')</em>' : '';
    parts.push('<li>' + badge(a.priority) + ' ' + owner + escapeHtml(a.task) + due + '</li>');
  }
  parts.push('</ul>');
}

// Key Quotes (only when present)
if (e.key_quotes && e.key_quotes.length > 0) {
  parts.push('<h2>Key Quotes</h2><ul>');
  for (const q of e.key_quotes) {
    parts.push('<li><em>&ldquo;' + escapeHtml(q) + '&rdquo;</em></li>');
  }
  parts.push('</ul>');
}

// Topics
if (e.topics && e.topics.length > 0) {
  parts.push('<h2>Topics</h2>');
  parts.push('<p>' + e.topics.map(t => escapeHtml(t)).join(' · ') + '</p>');
}

// Source Email
parts.push('<h2>Source Email</h2>');
parts.push(
  '<p>' +
  'From: '    + escapeHtml($json._email_from    || '') + '<br/>' +
  'Date: '    + escapeHtml($json._email_date    || '') + '<br/>' +
  'Subject: ' + escapeHtml($json._email_subject || '') +
  '</p>'
);

return {
  json: {
    ...$json,
    _confluence_title,
    _confluence_body: parts.join('\n'),
  },
};

// n8n Code Node: Expand Action Items
// Mode: Run Once for All Items
// Input: Create Confluence Page output (1 item)
// Output: N items — one per action item — each ready for Jira Create Issue

const items = $input.all();
const result = [];

for (const item of items) {
  const confluencePageId  = item.json.id    || '';
  const confluencePageUrl = item.json._links?.webui
    ? `https://shubhamgaur1.atlassian.net/wiki${item.json._links.webui}`
    : '';

  // Get extraction data from Parse LLM Response node
  const parsed     = $('Parse LLM Response').item.json;
  const extracted  = parsed._extracted;
  const actionItems = extracted.action_items || [];

  if (actionItems.length === 0) {
    // No action items — output one sentinel so the downstream Has Action Items? node can filter it
    result.push({
      json: {
        _no_action_items: true,
        _extracted: extracted,
        _confluence_page_url: confluencePageUrl,
        _confluence_page_id:  confluencePageId,
      },
    });
    continue;
  }

  for (let i = 0; i < actionItems.length; i++) {
    const ai = actionItems[i];
    const priority = _getPriority(ai);

    result.push({
      json: {
        _extracted:            extracted,
        _confluence_page_url:  confluencePageUrl,
        _confluence_page_id:   confluencePageId,
        _action_item_index:    i,
        _current_action_item:  ai,
        _priority:             priority,
        _is_high_priority:     priority === 'high',
        _jira_summary:         (ai.task || 'Action item').slice(0, 255),
        _jira_due_date:        ai.due   || null,
        _jira_owner:           ai.owner || null,
        _jira_labels:          ['meeting-generated', ...(extracted.topics || [])],
        _jira_description:     _buildDescription(extracted, ai, priority, confluencePageUrl, parsed),
        _email_subject:        parsed._email_subject || '',
        _email_from:           parsed._email_from    || '',
        _email_date:           parsed._email_date    || '',
      },
    });
  }
}

return result;

// ---- helpers ----------------------------------------------------------------

function _getPriority(item) {
  const p = (item.priority || '').toLowerCase();
  if (p === 'high' || p === 'medium' || p === 'low') return p;

  // Due-date heuristic for items without a priority field
  if (item.due) {
    try {
      const days = Math.floor(
        (new Date(item.due) - new Date()) / (1000 * 60 * 60 * 24)
      );
      if (days <= 14) return 'high';
      if (days <= 60) return 'medium';
    } catch (_) {}
  }
  return 'low';
}

function _buildDescription(extracted, ai, priority, confluenceUrl, parsed) {
  const lines = [];

  lines.push('Meeting: ' + (extracted.title || 'Meeting'));

  let meetingLine = 'Date: ' + (extracted.date || 'Unknown');
  if (extracted.platform && extracted.platform !== 'unknown') {
    meetingLine += ' | Platform: ' + extracted.platform;
  }
  if (extracted.duration_minutes) {
    meetingLine += ' | Duration: ' + extracted.duration_minutes + ' min';
  }
  lines.push(meetingLine);
  lines.push('');

  lines.push('Action Item:');
  lines.push(ai.task || 'Action item');
  lines.push('');

  const meta = [];
  if (ai.owner)  meta.push('Owner: ' + ai.owner);
  if (ai.due)    meta.push('Due: ' + ai.due);
  if (priority)  meta.push('Priority: ' + priority);
  if (meta.length) lines.push(meta.join('  |  '));

  lines.push('');
  lines.push('──────────────────────────────');
  lines.push('Meeting Summary:');
  lines.push(extracted.summary || '');

  if (extracted.decisions && extracted.decisions.length > 0) {
    lines.push('');
    lines.push('Decisions:');
    for (const d of extracted.decisions) lines.push('• ' + d);
  }

  if (extracted.attendees && extracted.attendees.length > 0) {
    lines.push('');
    lines.push('Attendees:');
    for (const a of extracted.attendees) {
      const name  = a.name || a.email || 'Unknown';
      const email = (a.email && a.name) ? ' (' + a.email + ')' : '';
      lines.push('• ' + name + email);
    }
  }

  lines.push('');
  lines.push('──────────────────────────────');
  if (confluenceUrl) lines.push('Confluence Note: ' + confluenceUrl);
  lines.push(
    'Source: "' + (parsed._email_subject || '') +
    '" from '  + (parsed._email_from    || '') +
    ' on '     + (parsed._email_date    || '')
  );

  return lines.join('\n');
}
